"""Independent arithmetic and output comparisons; standalone public consumer."""
exec(compile('#!/usr/bin/env python3\n# Independent literal calculation. Does not import model.py or read output.json.\nimport json, math\nS=12.363567245\nB0=197.220207\n# First-year independent parent/group check in billions:\nP=197.220207*.12\nPP=.95*(P+.664)-.664\nR=2098.856494*1.07\nPR=2098.856494*(1987.457699/2074.829309)*1.07\nPC=177.886377+.95*5.800495-.2035-.664\ncaps=[198.480742+P-.095*R,198.480742+P+20.296702-.10*R,198.480742+P+20.296702+50.662722-.125*R,PC+PP-.09*PR,PC+PP+19.997811-.095*PR,PC+PP+19.997811+48.890023-.12*PR]\navail=min(caps)\nD=min(.32*P+max(avail-.32*P,0)/3,avail)\nassert abs(D/S-0.6455773280747817)<1e-12\nDPS=[0.6455773280747817, 0.7430243549837846, 0.8398510810364377, 0.9453186243319953, 1.058905470125504, 1.1799309610945663, 1.3075432530153086, 1.4680609485457052, 1.644444350228474, 1.8334056074789262]\nB10=28.45123774305162\ndef literal(k,roe,g):\n    terminal=B10*(roe-g)/(k-g)\n    current=sum(d/(1+k)**(j+1) for j,d in enumerate(DPS))+terminal/(1+k)**10\n    tv5=sum(d/(1+k)**(j-4) for j,d in enumerate(DPS) if j>=5)+terminal/(1+k)**5\n    return [current,tv5]\na=literal(.11,.105,.025);b=literal(.10,.115,.03);base=literal(.105,.11,.03);sens=literal(.115,.11,.03)\nassert abs(a[0]-15.66674548344871)<1e-10\nassert abs(b[0]-19.880976369456615)<1e-10\nprint(json.dumps(dict(first_year_distribution=D/S,core_low=a,core_high=b,base=base,discount_plus_100bp=sens),indent=2))\n', __file__, "exec"), {"__file__": __file__, "__name__": "__main__"})
exec(compile("from pathlib import Path\nfrom decimal import Decimal as D,getcontext\nimport json\ngetcontext().prec=35\ndef d(x):return D(str(x))\nz=d(0);S=d('12.363567245');B0=d('217.884207')-20-d('.664');R0=d('2098.856494');PR0=R0*d('1987.457699')/d('2074.829309')\nb=B0;c=d('199.144742')-d('.664');pc=d('177.886377')+d('.95')*d('5.800495')-d('.2035')-d('.664');r=R0;pr=PR0;u=d('80.801804');pb=d('211.181249')-25+d('.95')*d('5.800495')-d('.2035')-d('.664');pa=d('3095.748880')*d('3286.757658')/d('3237.323805');pl=pa-pb-20\nrows=[]\nfor y,(rr,gg)in enumerate(zip([.12,.12,.118,.116,.114,.112,.11,.11,.11,.11],[.07,.07,.065,.06,.055,.05,.045,.04,.035,.03]),1):\n roe=d(rr);g=d(gg);oldr=r;oldpr=pr;share=d('.95');coupon=d('.664');mandatory=d('.33122')*S if y==1 else z\n at=d('20.296702')*oldr/R0;t2=d('50.662722')*oldr/R0;pat=d('19.997811')*oldpr/PR0;pt2=d('48.890023')*oldpr/PR0\n cost=d('.0332')*max(at-d('20.296702'),z)+d('.025')*max(t2-d('50.662722'),z)\n budget=b*roe-cost;desiredr=oldr*(1+g);ratio=oldpr/oldr;ar=pa/oldr;r=desiredr\n for _ in range(200):\n  profit=budget*(oldr+r)/(oldr+desiredr);pp=share*(profit+coupon)-coupon;up=max(profit-pp-g*max(b-pc,z),z)*min(max(d(y-5)/5,z),1);pp+=up\n  fund=(pl*d('1.1')+pb+pp-mandatory+20*r/R0)/ar\n  nr=min(desiredr,(c+profit-mandatory)/d('.095'),(c+profit+at-mandatory)/d('.10'),(c+profit+at+t2-mandatory)/d('.125'),(pc+pp-mandatory)/d('.09')/ratio,(pc+pp+pat-mandatory)/d('.095')/ratio,(pc+pp+pat+pt2-mandatory)/d('.12')/ratio,fund)\n  if abs(nr-r)<d('1e-24'):break\n  r=nr\n r=nr;pr=r*ratio;reserve=d('.015')*max(pr-oldpr,z);ul=u+pp-reserve\n av=min(c+profit-d('.095')*r,c+profit+at-d('.10')*r,c+profit+at+t2-d('.125')*r,pc+pp-d('.09')*pr,pc+pp+pat-d('.095')*pr,pc+pp+pat+pt2-d('.12')*pr)\n want=d('.32')*max(profit,z)+max(av-d('.32')*max(profit,z),z)/3\n newa=ar*r;newat=20*r/R0;fr=pl*d('1.1')+pb+pp+newat-newa;dist=max(z,min(max(want,mandatory),av,ul,fr))\n b+=profit-dist;c+=profit-dist;pc+=pp-dist;u=ul-dist;pb+=pp-dist;pa=newa;pl=newa-pb-newat\n rows.append({'year':y,'profit':profit,'distribution':dist,'book':b,'rwa':r,'parent_cet1_amount':pc,'parent_undistributed':u,'parent_assets':pa,'parent_liabilities':pl,'subsidiary_upstream':up})\ndef value(k,roe,g):\n k=d(k);roe=d(roe);g=d(g);tv=b*(roe-g)/(k-g)\n v=(sum(x['distribution']/(1+k)**x['year']for x in rows)+tv/(1+k)**10)/S\n y5=(sum(x['distribution']/(1+k)**(x['year']-5)for x in rows if x['year']>5)+tv/(1+k)**5)/S\n return v,y5\nprod=json.load(open(str(Path(__file__).resolve().parent / '2026-Q3-output.json')));err=[]\nfor a,o in zip(rows,prod['paths']['base']):\n for k,v in a.items():\n  if k!='year':err.append(abs(float(v)-o[k]))\nassert max(err)<1e-8,max(err)\nres={'annual_checks':len(err),'max_error':max(err),'values':{}}\nfor label,k,roe,g,expected in [('low',.11,.105,.025,prod['core']['low']),('high',.10,.115,.03,prod['core']['high']),('cost_plus_1pp',.115,.11,.03,prod['sensitivity']['discount_plus_100bp'])]:\n vals=value(k,roe,g);assert abs(float(vals[0])-expected['current'])<1e-10;assert abs(float(vals[1])-expected['terminal_y5'])<1e-10;res['values'][label]=[str(x)for x in vals]\nprint(json.dumps(res,ensure_ascii=False,indent=2))\n", __file__, "exec"), {"__file__": __file__, "__name__": "__main__"})
